import { registerXldb, type Worker } from "./worker.js";
import type { XldbSchema, XldbUpsertKey } from "./xldb-schema.js";

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type ManagedXldbConfig<
	Schema extends XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema>,
> = {
	type: "managed";
	/** The create-only user-facing table name. User renames are preserved. */
	initialTitle: string;
	/** The ordered, non-empty scalar columns used to address rows. */
	upsertKey: UpsertKey;
	/** The complete desired XLDB schema. */
	schema: Schema;
};

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbHandle<
	Schema extends XldbSchema = XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema> = XldbUpsertKey<Schema>,
> = {
	readonly _tag: "xldb";
	readonly key: string;
	readonly config: ManagedXldbConfig<Schema, UpsertKey>;
};

/**
 * Declare an XLDB table that Notion creates and reconciles on deploy.
 *
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB. For regular Notion databases, use
 * `worker.database()` and `worker.sync()` instead.
 */
export function createXldb<const S extends XldbSchema, const UK extends XldbUpsertKey<S>>(
	worker: Worker,
	key: string,
	config: ManagedXldbConfig<S, UK>,
): XldbHandle<S, UK> {
	registerXldb(worker, { key, config });
	return { _tag: "xldb", key, config };
}
